/* Insert GRP_STEP into MGCMTBLDAT */
BEGIN
	FOR REC IN (
		SELECT DISTINCT FACTORY FROM MWIPFACDEF
		MINUS
		SELECT DISTINCT FACTORY FROM MGCMTBLDAT 
		WHERE TABLE_NAME = 'GROUP_ITEM_NAME' AND KEY_1 = 'GRP_STEP'
		) 
	LOOP


	END LOOP;
END ;
/

