FROM MRASCGRREL REL, MRASCRRGRP CGR
WHERE REL.FACTORY = $FACTORY 
    AND REL.OPER=$1
	AND REL.FACTORY = CGR.FACTORY
	AND REL.CRR_GROUP = CGR.CRR_GROUP
ORDER BY CGR.CRR_GROUP
',' ',' ',' ',' ');
FROM MRASCRRDEF DEF, MRASCGRREL REL
WHERE REL.OPER = $1
  AND DEF.CRR_GROUP LIKE $2
  AND REL.FACTORY = $FACTORY 
  AND REL.FACTORY = REL.FACTORY 
  AND REL.CRR_GROUP = DEF.CRR_GROUP 
  AND DEF.CRR_ID NOT IN (
    SELECT CRR_ID 
	FROM MWIPCRRLOT 
	WHERE FACTORY = $FACTORY
  ) 
ORDER BY DEF.CRR_GROUP, DEF.CRR_ID
',' ',' ',' ',' ');
FROM MWIPLOTSTS 
WHERE FACTORY = $FACTORY 
  AND MAT_ID = $1 
  AND LOT_DEL_FLAG = '' ''
ORDER BY OPER, LOT_ID
',' ',' ',' ',' ');
FROM MRASRESLTH RHS, MWIPLOTHIS LHS
WHERE RHS.FACTORY = $FACTORY
  AND RHS.RES_ID = $1
  AND RHS.OPER LIKE $2
  AND RHS.RES_HIST_DEL_FLAG = '' ''
  AND RHS.EVENT_ID = ''END_LOT''
  AND RHS.LOT_HIST_DEL_FLAG = '' ''
  AND RHS.LOT_ID = LHS.LOT_ID
  AND RHS.LOT_HIST_SEQ = LHS.HIST_SEQ
ORDER BY RHS.TRAN_TIME
',' ',' ',' ',' ');
FROM MWIPLOTSTS LOT, MWIPOPRDEF OPR
WHERE LOT.FACTORY = $FACTORY 
    AND LOT.LOT_DEL_FLAG = '' ''
    AND LOT.FACTORY = OPR.FACTORY
    AND LOT.OPER = OPR.OPER
GROUP BY LOT.OPER, OPR.OPER_DESC
ORDER BY LOT.OPER
',' ',' ',' ',' ');
FROM MWIPMATFLW MFW, MWIPFLWOPR FOP, MWIPFLWDEF FLW, MWIPOPRDEF OPR
WHERE MFW.FACTORY = $FACTORY
  AND MFW.MAT_ID = $1
  AND MFW.MAT_VER = 1
  AND MFW.FACTORY = FOP.FACTORY
  AND MFW.FLOW = FOP.FLOW
  AND MFW.FACTORY = FLW.FACTORY
  AND MFW.FLOW = FLW.FLOW
  AND FOP.FACTORY = OPR.FACTORY
  AND FOP.OPER = OPR.OPER
ORDER BY MFW.FLOW_SEQ_NUM, FOP.SEQ_NUM
',' ',' ',' ',' ');

FROM MWIPOPRDEF 
WHERE FACTORY = $FACTORY 
ORDER BY OPER',' ',' ',' ',' ',' ',' ','ADMIN','20120112085128','ADMIN','20120112085645');
FROM MRASRESDEF 
WHERE FACTORY = $FACTORY 
ORDER BY RES_ID',' ',' ',' ',' ',' ',' ','ADMIN','20120112085145','ADMIN','20120112085521');







DELETE FROM MGCMTBLDAT 
WHERE FACTORY = 'SYSTEM' 
AND TABLE_NAME = 'FUNCTION_GROUP' 
AND KEY_1 IN (
  'ADMIN',
  'FMB',
  'INQUIRY',
  'RAS',
  'SETUP',
  'SPC',
  'TOP',
  'TRAN',
  'WIP'
);





BEGIN
    FOR REC IN (
        SELECT DISTINCT FACTORY FROM MGCMTBLDAT 
        WHERE TABLE_NAME = 'CMF_ITEM_NAME'
        ) 
    LOOP
        DELETE FROM MGCMTBLDAT 
        WHERE FACTORY = REC.FACTORY
        AND TABLE_NAME = 'CMF_ITEM_NAME'
        AND KEY_1 IN (
            'CMF_BOM_ORDER',
            'CMF_BOM_PART',
            'CMF_CALENDAR',
            'CMF_CHAR',
            'CMF_EVENT',
            'CMF_INSP_ITM',
            'CMF_LOT_CREATE',
            'CMF_MFO',
            'CMF_PDS_LOT',
            'CMF_PDS_RES',
            'CMF_TRN_ATTRIBUTE',
            'CMF_TRN_RECIPE'
        );
    END LOOP;
END ;
/

BEGIN
    FOR REC IN (
        SELECT DISTINCT FACTORY FROM MGCMTBLDAT 
        WHERE TABLE_NAME = 'GROUP_ITEM_NAME'
        ) 
    LOOP
        DELETE FROM MGCMTBLDAT 
        WHERE FACTORY = REC.FACTORY
        AND TABLE_NAME = 'GROUP_ITEM_NAME'
        AND KEY_1 IN (
            'GRP_EQUIP_RECIPE',
            'GRP_MASTER_RECIPE',
            'GRP_RMS_RECIPE'
        );
    END LOOP;
END ;
/

BEGIN
    FOR REC IN (
        SELECT DISTINCT FACTORY FROM MGCMTBLDAT 
        WHERE TABLE_NAME = 'PRINT_VARIABLE'
        ) 
    LOOP
        DELETE FROM MGCMTBLDAT 
        WHERE FACTORY = REC.FACTORY
        AND TABLE_NAME = 'PRINT_VARIABLE'
        AND KEY_1 IN (
            'CUSTOMER',
            'CUSTOMER_MAT_ID',
            'LOT_ID',
            'MAT_DESC',
            'MAT_ID',
            'MAT_TYPE',
            'ORDER_ID',
            'VENDOR'
        );
    END LOOP;
END ;
/




